sys_script_include.script:
var NowflixUtils = Class.create();
NowflixUtils.prototype = {
    initialize: function() {},
	refQualMedia: function() {

		var moviesToBeShown = [];
		var grMedia = new GlideRecord("x_875435_nowflix_media");
		grMedia.addQuery("state", "3");
		grMedia.query();

		while (grMedia.next()){
			var grReview = new GlideRecord("x_875435_nowflix_review");
			grReview.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4^media="+grMedia.sys_id);
			// grReview.addQuery("opened_by", gs.getUserID());
			// grReview.addQuery("media", grMedia.sys_id);
			// grReview.addQuery("state","!=","4");
			grReview.query();
			if(!grReview.next()){
				moviesToBeShown.push(grMedia.getUniqueValue());
			}
		}
		return "sys_idIN"+moviesToBeShown.join(",");
	},
    type: 'NowflixUtils'
};
